-- L3 checks/transfers, frozen Python guard semantics plus permanent identities.
CREATE TABLE checks_check (
 id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES ledger_company(id),
 identity_id TEXT NOT NULL UNIQUE REFERENCES documents_documentidentity(id),
 creation_digest TEXT NOT NULL CHECK(length(creation_digest)=64),
 revision INTEGER NOT NULL CHECK(revision>0), bank_id TEXT NOT NULL REFERENCES ledger_account(id),
 vendor_id TEXT REFERENCES directory_vendor(id),number_key TEXT NOT NULL CHECK(length(number_key)<=20),
 state TEXT NOT NULL CHECK(state IN('DRAFT','RECORDED','VOID'))
) STRICT, WITHOUT ROWID;
CREATE UNIQUE INDEX check_live_bank_number ON checks_check(company_id,bank_id,number_key) WHERE state<>'VOID' AND number_key<>'';
CREATE TABLE checks_checkrevision (
 id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES checks_check(id),number INTEGER NOT NULL CHECK(number>0),
 state TEXT NOT NULL CHECK(state IN('DRAFT','RECORDED','VOID')),action TEXT NOT NULL,reason TEXT NOT NULL CHECK(length(reason)<=500),
 actor_id TEXT NOT NULL REFERENCES fb_user(id),actor_name TEXT NOT NULL,created_at TEXT NOT NULL,
 bank_id TEXT NOT NULL REFERENCES ledger_account(id),bank_snapshot TEXT NOT NULL CHECK(json_valid(bank_snapshot)),
 payee_kind TEXT NOT NULL CHECK(payee_kind IN('VENDOR','OTHER')),vendor_id TEXT REFERENCES directory_vendor(id),payee_name TEXT NOT NULL CHECK(length(payee_name) BETWEEN 1 AND 120),
 payee_snapshot TEXT NOT NULL CHECK(json_valid(payee_snapshot)),address TEXT NOT NULL CHECK(length(address)<=1000),company_snapshot TEXT NOT NULL CHECK(json_valid(company_snapshot)),
 date TEXT NOT NULL CHECK(date(date) IS date),check_number TEXT NOT NULL CHECK(length(check_number)<=20),print_later INTEGER NOT NULL CHECK(print_later IN(0,1)),
 journal_id TEXT REFERENCES ledger_journal(id),reversal_id TEXT REFERENCES ledger_journal(id),review_digest TEXT NOT NULL,
 memo TEXT NOT NULL CHECK(length(memo)<=2000),total INTEGER NOT NULL CHECK(total BETWEEN 1 AND 9999999999999999),UNIQUE(document_id,number)
) STRICT, WITHOUT ROWID;
CREATE TABLE checks_checkline (
 id TEXT PRIMARY KEY,revision_id TEXT NOT NULL REFERENCES checks_checkrevision(id),position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 50),
 tab TEXT NOT NULL CHECK(tab IN('EXPENSE','ITEM')),account_id TEXT REFERENCES ledger_account(id),account_snapshot TEXT NOT NULL CHECK(json_valid(account_snapshot)),
 item_id TEXT REFERENCES directory_item(id),item_snapshot TEXT NOT NULL CHECK(json_valid(item_snapshot)),description TEXT NOT NULL CHECK(length(description)<=1000),
 quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 999999999999999999),rate INTEGER NOT NULL CHECK(rate BETWEEN 1 AND 9999999999999999),amount INTEGER NOT NULL CHECK(amount BETWEEN 1 AND 9999999999999999),UNIQUE(revision_id,position)
) STRICT, WITHOUT ROWID;
CREATE TABLE transfers_transfer (
 id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES ledger_company(id),identity_id TEXT NOT NULL UNIQUE REFERENCES documents_documentidentity(id),
 creation_digest TEXT NOT NULL CHECK(length(creation_digest)=64),review_digest TEXT NOT NULL CHECK(length(review_digest)=64),
 from_account_id TEXT NOT NULL REFERENCES ledger_account(id),to_account_id TEXT NOT NULL REFERENCES ledger_account(id),
 from_snapshot TEXT NOT NULL CHECK(json_valid(from_snapshot)),to_snapshot TEXT NOT NULL CHECK(json_valid(to_snapshot)),company_snapshot TEXT NOT NULL CHECK(json_valid(company_snapshot)),
 date TEXT NOT NULL CHECK(date(date) IS date),amount INTEGER NOT NULL CHECK(amount BETWEEN 1 AND 9999999999999999),memo TEXT NOT NULL CHECK(length(memo)<=2000),
 journal_id TEXT NOT NULL UNIQUE REFERENCES ledger_journal(id),actor_id TEXT NOT NULL REFERENCES fb_user(id),actor_name TEXT NOT NULL,created_at TEXT NOT NULL,
 CHECK(from_account_id<>to_account_id)
) STRICT, WITHOUT ROWID;
CREATE TABLE transfers_transfervoid (
 id TEXT PRIMARY KEY,transfer_id TEXT NOT NULL UNIQUE REFERENCES transfers_transfer(id),journal_id TEXT NOT NULL UNIQUE REFERENCES ledger_journal(id),
 date TEXT NOT NULL CHECK(date(date) IS date),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 500),
 actor_id TEXT NOT NULL REFERENCES fb_user(id),actor_name TEXT NOT NULL,created_at TEXT NOT NULL
) STRICT, WITHOUT ROWID;
CREATE TRIGGER fb_check_insert BEFORE INSERT ON checks_check BEGIN
 SELECT RAISE(ABORT,'check_immutable_ownership: Checks cannot replace existing history') WHERE EXISTS(SELECT 1 FROM checks_check WHERE id=NEW.id OR identity_id=NEW.identity_id OR (company_id=NEW.company_id AND bank_id=NEW.bank_id AND number_key=NEW.number_key AND number_key<>'' AND state<>'VOID' AND NEW.state<>'VOID'));
 SELECT RAISE(ABORT,'check_identity_scope: Invalid check identity') WHERE NEW.revision<>1 OR NEW.state<>'DRAFT' OR NOT EXISTS(SELECT 1 FROM documents_documentidentity WHERE id=NEW.identity_id AND company_id=NEW.company_id AND kind='CHK');
END;
CREATE TRIGGER fb_check_update BEFORE UPDATE ON checks_check BEGIN
 SELECT RAISE(ABORT,'check_immutable_ownership: Check ownership is immutable; revisions advance by one') WHERE NEW.id IS NOT OLD.id OR NEW.company_id IS NOT OLD.company_id OR NEW.identity_id IS NOT OLD.identity_id OR NEW.creation_digest IS NOT OLD.creation_digest OR OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1 OR NOT EXISTS(SELECT 1 FROM fb_seal WHERE kind='check_revision' AND doc_id=OLD.id||':'||OLD.revision);
 SELECT RAISE(ABORT,'check_immutable_ownership: Update would replace existing history') WHERE EXISTS(SELECT 1 FROM checks_check WHERE id<>OLD.id AND (id=NEW.id OR identity_id=NEW.identity_id OR (company_id=NEW.company_id AND bank_id=NEW.bank_id AND number_key=NEW.number_key AND number_key<>'' AND state<>'VOID' AND NEW.state<>'VOID')));
END;
CREATE TRIGGER fb_check_due_insert AFTER INSERT ON checks_check BEGIN INSERT INTO fb_seal_due VALUES('check_revision',NEW.id||':'||NEW.revision); END;
CREATE TRIGGER fb_check_due_update AFTER UPDATE ON checks_check BEGIN INSERT INTO fb_seal_due VALUES('check_revision',NEW.id||':'||NEW.revision); END;
CREATE TRIGGER fb_check_revision_insert BEFORE INSERT ON checks_checkrevision BEGIN
 SELECT RAISE(ABORT,'check_history_immutable: Check revisions are immutable') WHERE EXISTS(SELECT 1 FROM checks_checkrevision WHERE id=NEW.id OR (document_id=NEW.document_id AND number=NEW.number));
 SELECT RAISE(ABORT,'check_revision_scope: Invalid check revision ownership') WHERE NOT EXISTS(SELECT 1 FROM checks_check c JOIN ledger_account a ON a.company_id=c.company_id WHERE c.id=NEW.document_id AND c.revision=NEW.number AND a.id=NEW.bank_id AND (NEW.vendor_id IS NULL OR EXISTS(SELECT 1 FROM directory_vendor WHERE id=NEW.vendor_id AND company_id=c.company_id))) OR EXISTS(SELECT 1 FROM fb_seal WHERE kind='check_revision' AND doc_id=NEW.document_id||':'||NEW.number);
 SELECT RAISE(ABORT,'check_fields: Invalid check payee, number or text fields') WHERE (NEW.payee_kind='VENDOR')<>(NEW.vendor_id IS NOT NULL) OR trim(NEW.payee_name)='' OR NEW.check_number<>trim(NEW.check_number,char(32,9,10,13,12,11)) OR NEW.print_later=(NEW.check_number<>'');
 SELECT RAISE(ABORT,'check_transition: Invalid check state transition') WHERE (NEW.number=1 AND (NEW.state<>'DRAFT' OR NEW.action<>'created')) OR (NEW.number>1 AND NOT EXISTS(SELECT 1 FROM checks_checkrevision p WHERE p.document_id=NEW.document_id AND p.number=NEW.number-1 AND ((p.state='DRAFT' AND NEW.state='DRAFT' AND NEW.action='revised') OR (p.state='DRAFT' AND NEW.state='RECORDED' AND NEW.action='recorded') OR (p.state='RECORDED' AND NEW.state='RECORDED' AND NEW.action='numbered' AND p.print_later=1 AND NEW.print_later=0 AND NEW.check_number<>'') OR (p.state='RECORDED' AND NEW.state='VOID' AND NEW.action='voided'))));
 SELECT RAISE(ABORT,'check_root_current: Check root index does not match revision') WHERE NOT EXISTS(SELECT 1 FROM checks_check WHERE id=NEW.document_id AND bank_id=NEW.bank_id AND vendor_id IS NEW.vendor_id AND state=NEW.state AND number_key=NEW.check_number);
 SELECT RAISE(ABORT,'check_void_reason: Void requires reason') WHERE NEW.state='VOID' AND trim(NEW.reason)='';
 SELECT RAISE(ABORT,'check_posting_link: Invalid check posting linkage') WHERE
 (NEW.state='DRAFT' AND (NEW.journal_id IS NOT NULL OR NEW.reversal_id IS NOT NULL OR NEW.review_digest<>'')) OR
 (NEW.state IN('RECORDED','VOID') AND (length(NEW.review_digest)<>64 OR NOT EXISTS(SELECT 1 FROM ledger_journal j JOIN checks_check c ON c.identity_id=j.source_id WHERE c.id=NEW.document_id AND j.id=NEW.journal_id AND j.company_id=c.company_id AND j.status='POSTED' AND j.reversal_of_id IS NULL AND j.date=NEW.date))) OR
 (NEW.state='RECORDED' AND NEW.reversal_id IS NOT NULL) OR
 (NEW.action IN('numbered','voided') AND NOT EXISTS(SELECT 1 FROM checks_checkrevision p WHERE p.document_id=NEW.document_id AND p.number=NEW.number-1 AND p.journal_id=NEW.journal_id AND p.review_digest=NEW.review_digest)) OR
 (NEW.state='VOID' AND NOT EXISTS(SELECT 1 FROM ledger_journal j JOIN checks_check c ON c.identity_id=j.source_id WHERE c.id=NEW.document_id AND j.id=NEW.reversal_id AND j.reversal_of_id=NEW.journal_id AND j.status='POSTED' AND j.date>=NEW.date));
 SELECT RAISE(ABORT,'check_financial_immutable: Recording, numbering and void preserve financial evidence') WHERE NEW.state IN('RECORDED','VOID') AND NOT EXISTS(SELECT 1 FROM checks_checkrevision p WHERE p.document_id=NEW.document_id AND p.number=NEW.number-1 AND p.bank_id IS NEW.bank_id AND p.bank_snapshot IS NEW.bank_snapshot AND p.payee_kind IS NEW.payee_kind AND p.vendor_id IS NEW.vendor_id AND p.payee_name IS NEW.payee_name AND p.payee_snapshot IS NEW.payee_snapshot AND p.address IS NEW.address AND p.company_snapshot IS NEW.company_snapshot AND p.date IS NEW.date AND p.memo IS NEW.memo AND p.total IS NEW.total AND (NEW.action='numbered' OR (p.check_number=NEW.check_number AND p.print_later=NEW.print_later)));
 SELECT RAISE(ABORT,'check_draft_bank: Choose an active designated bank') WHERE NEW.state='DRAFT' AND NOT EXISTS(SELECT 1 FROM checks_check c JOIN ledger_account a ON a.company_id=c.company_id JOIN documents_accountingsetup s ON s.company_id=c.company_id JOIN documents_designatedbank d ON d.setup_id=s.id AND d.account_id=a.id WHERE c.id=NEW.document_id AND a.id=NEW.bank_id AND a.kind='ASSET' AND a.active=1 AND a.postable=1);
 SELECT RAISE(ABORT,'check_vendor_eligible: New draft vendors must be active') WHERE NEW.state='DRAFT' AND NEW.vendor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM directory_vendor v WHERE v.id=NEW.vendor_id AND (v.active=1 OR EXISTS(SELECT 1 FROM checks_checkrevision p WHERE p.document_id=NEW.document_id AND p.number=NEW.number-1 AND p.vendor_id=v.id)));
END;
CREATE TRIGGER fb_check_line_insert BEFORE INSERT ON checks_checkline BEGIN
 SELECT RAISE(ABORT,'check_history_immutable: Check lines are immutable') WHERE EXISTS(SELECT 1 FROM checks_checkline WHERE id=NEW.id OR (revision_id=NEW.revision_id AND position=NEW.position));
 SELECT RAISE(ABORT,'check_line_scope: Invalid check line scope or committed history') WHERE NOT EXISTS(SELECT 1 FROM checks_checkrevision r JOIN checks_check c ON c.id=r.document_id WHERE r.id=NEW.revision_id AND r.number=c.revision AND NOT EXISTS(SELECT 1 FROM fb_seal WHERE kind='check_revision' AND doc_id=c.id||':'||c.revision) AND (NEW.item_id IS NULL OR EXISTS(SELECT 1 FROM directory_item WHERE id=NEW.item_id AND company_id=c.company_id)) AND (NEW.account_id IS NULL OR EXISTS(SELECT 1 FROM ledger_account WHERE id=NEW.account_id AND company_id=c.company_id)));
 SELECT RAISE(ABORT,'check_line_calculation: Invalid check line calculation or shape') WHERE fb_payables_line_valid(NEW.quantity,NEW.rate,NEW.amount)=0 OR (NEW.tab='EXPENSE' AND (NEW.item_id IS NOT NULL OR NEW.quantity<>10000)) OR (NEW.tab='ITEM' AND NEW.item_id IS NULL);
 SELECT RAISE(ABORT,'check_item_eligible: New draft items must be active') WHERE NEW.item_id IS NOT NULL AND EXISTS(SELECT 1 FROM checks_checkrevision WHERE id=NEW.revision_id AND state='DRAFT') AND NOT EXISTS(SELECT 1 FROM directory_item i JOIN checks_checkrevision r ON r.id=NEW.revision_id WHERE i.id=NEW.item_id AND (i.active=1 OR EXISTS(SELECT 1 FROM checks_checkrevision p JOIN checks_checkline l ON l.revision_id=p.id WHERE p.document_id=r.document_id AND p.number=r.number-1 AND l.item_id=i.id)));
 SELECT RAISE(ABORT,'check_line_eligible: Invalid draft purchase account') WHERE NEW.account_id IS NOT NULL AND EXISTS(SELECT 1 FROM checks_checkrevision WHERE id=NEW.revision_id AND state='DRAFT') AND NOT EXISTS(SELECT 1 FROM checks_checkrevision r JOIN checks_check c ON c.id=r.document_id JOIN ledger_account a ON a.company_id=c.company_id WHERE r.id=NEW.revision_id AND a.id=NEW.account_id AND a.id<>r.bank_id AND a.postable=1 AND a.detail_type IN('BANK','OTHER_CURRENT_ASSET','FIXED_ASSET','OTHER_ASSET','CREDIT_CARD','OTHER_CURRENT_LIABILITY','LONG_TERM_LIABILITY','EQUITY','COST_OF_GOODS_SOLD','EXPENSE','OTHER_EXPENSE') AND NOT EXISTS(SELECT 1 FROM fb_control_accounts WHERE company_id=c.company_id AND account_id=a.id) AND (a.active=1 OR EXISTS(SELECT 1 FROM checks_checkrevision p JOIN checks_checkline l ON l.revision_id=p.id WHERE p.document_id=c.id AND p.number=r.number-1 AND l.account_id=a.id)));
END;
CREATE TRIGGER fb_check_seal BEFORE INSERT ON fb_seal WHEN NEW.kind='check_revision' BEGIN
 SELECT RAISE(ABORT,'check_complete: Incomplete or inconsistent check totals') WHERE NOT EXISTS(SELECT 1 FROM checks_checkrevision r JOIN checks_check c ON c.id=r.document_id WHERE NEW.doc_id=c.id||':'||c.revision AND r.number=c.revision AND c.bank_id=r.bank_id AND c.vendor_id IS r.vendor_id AND c.state=r.state AND c.number_key=r.check_number AND (SELECT count(*) FROM checks_checkline WHERE revision_id=r.id) BETWEEN 1 AND 50 AND (SELECT min(position) FROM checks_checkline WHERE revision_id=r.id)=1 AND (SELECT max(position) FROM checks_checkline WHERE revision_id=r.id)=(SELECT count(*) FROM checks_checkline WHERE revision_id=r.id) AND r.total=(SELECT sum(amount) FROM checks_checkline WHERE revision_id=r.id));
 SELECT RAISE(ABORT,'check_post_eligible: Active eligible posting parents required') WHERE EXISTS(SELECT 1 FROM checks_checkrevision r JOIN checks_check c ON c.id=r.document_id WHERE NEW.doc_id=c.id||':'||r.number AND r.action='recorded' AND (
 (r.vendor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM directory_vendor WHERE id=r.vendor_id AND company_id=c.company_id AND active=1)) OR
 NOT EXISTS(SELECT 1 FROM ledger_account a JOIN documents_accountingsetup s ON s.company_id=a.company_id JOIN documents_designatedbank d ON d.setup_id=s.id AND d.account_id=a.id WHERE a.id=r.bank_id AND a.company_id=c.company_id AND a.kind='ASSET' AND a.active=1 AND a.postable=1) OR
 EXISTS(SELECT 1 FROM checks_checkline l WHERE l.revision_id=r.id AND ((l.item_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM directory_item WHERE id=l.item_id AND company_id=c.company_id AND active=1)) OR NOT EXISTS(SELECT 1 FROM ledger_account a WHERE a.id=l.account_id AND a.company_id=c.company_id AND a.active=1 AND a.postable=1 AND a.id<>r.bank_id AND a.detail_type IN('BANK','OTHER_CURRENT_ASSET','FIXED_ASSET','OTHER_ASSET','CREDIT_CARD','OTHER_CURRENT_LIABILITY','LONG_TERM_LIABILITY','EQUITY','COST_OF_GOODS_SOLD','EXPENSE','OTHER_EXPENSE') AND NOT EXISTS(SELECT 1 FROM fb_control_accounts WHERE company_id=c.company_id AND account_id=a.id))))));
 SELECT RAISE(ABORT,'check_financial_immutable: Recording, numbering and void must copy exact lines') WHERE EXISTS(SELECT 1 FROM checks_checkrevision r WHERE NEW.doc_id=r.document_id||':'||r.number AND r.state IN('RECORDED','VOID') AND (
 EXISTS(SELECT position,tab,account_id,account_snapshot,item_id,item_snapshot,description,quantity,rate,amount FROM checks_checkline WHERE revision_id=r.id EXCEPT SELECT position,tab,account_id,account_snapshot,item_id,item_snapshot,description,quantity,rate,amount FROM checks_checkline WHERE revision_id=(SELECT id FROM checks_checkrevision WHERE document_id=r.document_id AND number=r.number-1)) OR
 EXISTS(SELECT position,tab,account_id,account_snapshot,item_id,item_snapshot,description,quantity,rate,amount FROM checks_checkline WHERE revision_id=(SELECT id FROM checks_checkrevision WHERE document_id=r.document_id AND number=r.number-1) EXCEPT SELECT position,tab,account_id,account_snapshot,item_id,item_snapshot,description,quantity,rate,amount FROM checks_checkline WHERE revision_id=r.id)));
 SELECT RAISE(ABORT,'check_journal_split: Check must match exact bank credit / line debit posting and frozen accounts') WHERE EXISTS(SELECT 1 FROM checks_checkrevision r JOIN checks_check c ON c.id=r.document_id WHERE NEW.doc_id=c.id||':'||r.number AND r.state IN('RECORDED','VOID') AND (
 NOT EXISTS(SELECT 1 FROM documents_documentaccount WHERE source_id=c.identity_id AND role='bank' AND account_id=r.bank_id AND account_kind='ASSET') OR
 EXISTS(SELECT 1 FROM checks_checkline l WHERE l.revision_id=r.id AND (l.account_id IS NULL OR l.account_id=r.bank_id OR NOT EXISTS(SELECT 1 FROM documents_documentaccount WHERE source_id=c.identity_id AND role='debit:'||l.position AND account_id=l.account_id))) OR
 (SELECT count(*) FROM documents_documentaccount WHERE source_id=c.identity_id)<>(SELECT count(*)+1 FROM checks_checkline WHERE revision_id=r.id) OR
 (SELECT count(*) FROM ledger_journalline WHERE journal_id=r.journal_id)<>(SELECT count(DISTINCT account_id)+1 FROM checks_checkline WHERE revision_id=r.id) OR
 NOT EXISTS(SELECT 1 FROM ledger_journalline WHERE journal_id=r.journal_id AND account_id=r.bank_id AND debit=0 AND credit=r.total) OR
 EXISTS(SELECT account_id,sum(amount),0 FROM checks_checkline WHERE revision_id=r.id GROUP BY account_id EXCEPT SELECT account_id,debit,credit FROM ledger_journalline WHERE journal_id=r.journal_id)));
END;
CREATE TRIGGER fb_check_payment_insert BEFORE INSERT ON checks_check WHEN NEW.state<>'VOID' AND NEW.number_key<>'' BEGIN
 SELECT RAISE(ABORT,'check_payment_number: Check number already used by a live bill payment on this bank') WHERE EXISTS(SELECT 1 FROM fb_payables_live_checks WHERE company_id=NEW.company_id AND bank_id=NEW.bank_id AND number=NEW.number_key);
END;
CREATE TRIGGER fb_check_payment_update BEFORE UPDATE ON checks_check WHEN NEW.state<>'VOID' AND NEW.number_key<>'' BEGIN
 SELECT RAISE(ABORT,'check_payment_number: Check number already used by a live bill payment on this bank') WHERE EXISTS(SELECT 1 FROM fb_payables_live_checks WHERE company_id=NEW.company_id AND bank_id=NEW.bank_id AND number=NEW.number_key);
END;
CREATE TRIGGER fb_checks_payment_collision BEFORE INSERT ON payables_billpayment WHEN NEW.method='CHECK' AND length(NEW.reference) BETWEEN 1 AND 20 AND NEW.reference NOT GLOB '*[^0-9]*' BEGIN
 SELECT RAISE(ABORT,'check_payment_number: Check number already used on this bank') WHERE EXISTS(SELECT 1 FROM checks_check WHERE company_id=NEW.company_id AND bank_id=NEW.bank_id AND number_key=NEW.reference AND state<>'VOID');
END;
CREATE TRIGGER fb_transfer_insert BEFORE INSERT ON transfers_transfer BEGIN
 SELECT RAISE(ABORT,'transfer_immutable: Transfer history is immutable') WHERE EXISTS(SELECT 1 FROM transfers_transfer WHERE id=NEW.id OR identity_id=NEW.identity_id OR journal_id=NEW.journal_id);
 SELECT RAISE(ABORT,'transfer_scope: Invalid transfer ownership, accounts or posting') WHERE NOT EXISTS(SELECT 1 FROM documents_documentidentity WHERE id=NEW.identity_id AND company_id=NEW.company_id AND kind='TRF') OR
 (SELECT count(*) FROM ledger_account WHERE id IN(NEW.from_account_id,NEW.to_account_id) AND company_id=NEW.company_id AND kind='ASSET' AND active=1 AND postable=1)<>2 OR
 (SELECT count(*) FROM documents_designatedbank d JOIN documents_accountingsetup s ON s.id=d.setup_id WHERE s.company_id=NEW.company_id AND d.account_id IN(NEW.from_account_id,NEW.to_account_id))<>2 OR
 NOT EXISTS(SELECT 1 FROM ledger_journal WHERE id=NEW.journal_id AND company_id=NEW.company_id AND source_id=NEW.identity_id AND status='POSTED' AND reversal_of_id IS NULL AND date=NEW.date);
 SELECT RAISE(ABORT,'transfer_control_account: Transfers cannot use a control account') WHERE EXISTS(SELECT 1 FROM fb_control_accounts WHERE company_id=NEW.company_id AND account_id IN(NEW.from_account_id,NEW.to_account_id));
 SELECT RAISE(ABORT,'transfer_journal_split: Transfer journal must be exactly one credit on the from bank and one debit on the to bank') WHERE (SELECT count(*) FROM ledger_journalline WHERE journal_id=NEW.journal_id)<>2 OR NOT EXISTS(SELECT 1 FROM ledger_journalline WHERE journal_id=NEW.journal_id AND account_id=NEW.from_account_id AND debit=0 AND credit=NEW.amount) OR NOT EXISTS(SELECT 1 FROM ledger_journalline WHERE journal_id=NEW.journal_id AND account_id=NEW.to_account_id AND debit=NEW.amount AND credit=0);
 SELECT RAISE(ABORT,'transfer_account_evidence: Transfer account evidence must be exactly from and to') WHERE (SELECT count(*) FROM documents_documentaccount WHERE source_id=NEW.identity_id)<>2 OR NOT EXISTS(SELECT 1 FROM documents_documentaccount WHERE source_id=NEW.identity_id AND role='from' AND account_id=NEW.from_account_id) OR NOT EXISTS(SELECT 1 FROM documents_documentaccount WHERE source_id=NEW.identity_id AND role='to' AND account_id=NEW.to_account_id);
END;
CREATE TRIGGER fb_transfer_void_insert BEFORE INSERT ON transfers_transfervoid BEGIN
 SELECT RAISE(ABORT,'transfer_immutable: Transfer void history is immutable') WHERE EXISTS(SELECT 1 FROM transfers_transfervoid WHERE id=NEW.id OR transfer_id=NEW.transfer_id OR journal_id=NEW.journal_id);
 SELECT RAISE(ABORT,'transfer_void_link: Invalid transfer void') WHERE NOT EXISTS(SELECT 1 FROM transfers_transfer t JOIN ledger_journal j ON j.source_id=t.identity_id AND j.company_id=t.company_id AND j.reversal_of_id=t.journal_id WHERE t.id=NEW.transfer_id AND NEW.date>=t.date AND j.id=NEW.journal_id AND j.date=NEW.date AND j.status='POSTED');
END;
CREATE TRIGGER fb_checks_journal_due AFTER INSERT ON ledger_journal WHEN EXISTS(SELECT 1 FROM documents_documentidentity WHERE id=NEW.source_id AND kind='CHK') BEGIN INSERT INTO fb_seal_due VALUES('checks_journal',NEW.id); END;
CREATE TRIGGER fb_transfer_journal_due AFTER INSERT ON ledger_journal WHEN EXISTS(SELECT 1 FROM documents_documentidentity WHERE id=NEW.source_id AND kind='TRF') BEGIN INSERT INTO fb_seal_due VALUES('transfer_journal',NEW.id); END;
CREATE TRIGGER fb_checks_journal_seal BEFORE INSERT ON fb_seal WHEN NEW.kind='checks_journal' BEGIN
 SELECT RAISE(ABORT,'check_journal_owner: Check journals require the owning check lifecycle') WHERE NOT EXISTS(SELECT 1 FROM ledger_journal j JOIN checks_check c ON c.identity_id=j.source_id JOIN checks_checkrevision r ON r.document_id=c.id AND r.number=c.revision JOIN fb_seal s ON s.kind='check_revision' AND s.doc_id=c.id||':'||c.revision WHERE j.id=NEW.doc_id AND j.status='POSTED' AND r.state IN('RECORDED','VOID') AND ((j.reversal_of_id IS NULL AND r.journal_id=j.id) OR (r.state='VOID' AND r.journal_id=j.reversal_of_id AND r.reversal_id=j.id)));
END;
CREATE TRIGGER fb_transfer_journal_seal BEFORE INSERT ON fb_seal WHEN NEW.kind='transfer_journal' BEGIN
 SELECT RAISE(ABORT,'transfer_journal_owner: Transfer journals require the owning transfer lifecycle') WHERE NOT EXISTS(SELECT 1 FROM ledger_journal j JOIN transfers_transfer t ON t.identity_id=j.source_id WHERE j.id=NEW.doc_id AND j.status='POSTED' AND ((j.reversal_of_id IS NULL AND t.journal_id=j.id) OR (t.journal_id=j.reversal_of_id AND EXISTS(SELECT 1 FROM transfers_transfervoid v WHERE v.transfer_id=t.id AND v.journal_id=j.id))));
END;
CREATE TRIGGER fb_checks_late_reference BEFORE INSERT ON documents_documentaccount WHEN EXISTS(SELECT 1 FROM ledger_journal j JOIN fb_seal s ON s.kind IN('checks_journal','transfer_journal') AND s.doc_id=j.id WHERE j.source_id=NEW.source_id) BEGIN SELECT RAISE(ABORT,'check_late_reference: Cannot append posted account evidence'); END;

CREATE TRIGGER fb_checks_check_primary_key BEFORE UPDATE OF id ON checks_check WHEN NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'checks_primary_key: Primary keys never change'); END;
CREATE TRIGGER fb_checks_check_delete BEFORE DELETE ON checks_check BEGIN SELECT RAISE(ABORT,'checks_history_immutable: History cannot be deleted'); END;

CREATE TRIGGER fb_checks_checkrevision_primary_key BEFORE UPDATE OF id ON checks_checkrevision WHEN NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'checks_primary_key: Primary keys never change'); END;
CREATE TRIGGER fb_checks_checkrevision_update BEFORE UPDATE ON checks_checkrevision BEGIN SELECT RAISE(ABORT,'checks_history_immutable: History is immutable'); END;
CREATE TRIGGER fb_checks_checkrevision_delete BEFORE DELETE ON checks_checkrevision BEGIN SELECT RAISE(ABORT,'checks_history_immutable: History cannot be deleted'); END;

CREATE TRIGGER fb_checks_checkline_primary_key BEFORE UPDATE OF id ON checks_checkline WHEN NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'checks_primary_key: Primary keys never change'); END;
CREATE TRIGGER fb_checks_checkline_update BEFORE UPDATE ON checks_checkline BEGIN SELECT RAISE(ABORT,'checks_history_immutable: History is immutable'); END;
CREATE TRIGGER fb_checks_checkline_delete BEFORE DELETE ON checks_checkline BEGIN SELECT RAISE(ABORT,'checks_history_immutable: History cannot be deleted'); END;

CREATE TRIGGER fb_transfers_transfer_primary_key BEFORE UPDATE OF id ON transfers_transfer WHEN NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'checks_primary_key: Primary keys never change'); END;
CREATE TRIGGER fb_transfers_transfer_update BEFORE UPDATE ON transfers_transfer BEGIN SELECT RAISE(ABORT,'checks_history_immutable: History is immutable'); END;
CREATE TRIGGER fb_transfers_transfer_delete BEFORE DELETE ON transfers_transfer BEGIN SELECT RAISE(ABORT,'checks_history_immutable: History cannot be deleted'); END;

CREATE TRIGGER fb_transfers_transfervoid_primary_key BEFORE UPDATE OF id ON transfers_transfervoid WHEN NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'checks_primary_key: Primary keys never change'); END;
CREATE TRIGGER fb_transfers_transfervoid_update BEFORE UPDATE ON transfers_transfervoid BEGIN SELECT RAISE(ABORT,'checks_history_immutable: History is immutable'); END;
CREATE TRIGGER fb_transfers_transfervoid_delete BEFORE DELETE ON transfers_transfervoid BEGIN SELECT RAISE(ABORT,'checks_history_immutable: History cannot be deleted'); END;
CREATE TRIGGER fb_checks_ledger_account_kept BEFORE DELETE ON ledger_account WHEN EXISTS(SELECT 1 FROM checks_check WHERE bank_id=OLD.id) OR EXISTS(SELECT 1 FROM checks_checkrevision WHERE bank_id=OLD.id) OR EXISTS(SELECT 1 FROM checks_checkline WHERE account_id=OLD.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE from_account_id=OLD.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE to_account_id=OLD.id) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Referenced parents cannot be deleted'); END;
CREATE TRIGGER fb_checks_ledger_account_insert BEFORE INSERT ON ledger_account WHEN EXISTS(SELECT 1 FROM ledger_account a WHERE (a.id=NEW.id OR (a.company_id=NEW.company_id AND a.code=NEW.code)) AND (EXISTS(SELECT 1 FROM checks_check WHERE bank_id=a.id) OR EXISTS(SELECT 1 FROM checks_checkrevision WHERE bank_id=a.id) OR EXISTS(SELECT 1 FROM checks_checkline WHERE account_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE from_account_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE to_account_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
CREATE TRIGGER fb_checks_ledger_account_update BEFORE UPDATE ON ledger_account WHEN EXISTS(SELECT 1 FROM ledger_account a WHERE (a.id=NEW.id OR (a.company_id=NEW.company_id AND a.code=NEW.code)) AND a.id<>OLD.id AND (EXISTS(SELECT 1 FROM checks_check WHERE bank_id=a.id) OR EXISTS(SELECT 1 FROM checks_checkrevision WHERE bank_id=a.id) OR EXISTS(SELECT 1 FROM checks_checkline WHERE account_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE from_account_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE to_account_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
CREATE TRIGGER fb_checks_directory_vendor_kept BEFORE DELETE ON directory_vendor WHEN EXISTS(SELECT 1 FROM checks_check WHERE vendor_id=OLD.id) OR EXISTS(SELECT 1 FROM checks_checkrevision WHERE vendor_id=OLD.id) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Referenced parents cannot be deleted'); END;
CREATE TRIGGER fb_checks_directory_vendor_insert BEFORE INSERT ON directory_vendor WHEN EXISTS(SELECT 1 FROM directory_vendor a WHERE (a.id=NEW.id OR 0) AND (EXISTS(SELECT 1 FROM checks_check WHERE vendor_id=a.id) OR EXISTS(SELECT 1 FROM checks_checkrevision WHERE vendor_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
CREATE TRIGGER fb_checks_directory_vendor_update BEFORE UPDATE ON directory_vendor WHEN EXISTS(SELECT 1 FROM directory_vendor a WHERE (a.id=NEW.id OR 0) AND a.id<>OLD.id AND (EXISTS(SELECT 1 FROM checks_check WHERE vendor_id=a.id) OR EXISTS(SELECT 1 FROM checks_checkrevision WHERE vendor_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
CREATE TRIGGER fb_checks_directory_item_kept BEFORE DELETE ON directory_item WHEN EXISTS(SELECT 1 FROM checks_checkline WHERE item_id=OLD.id) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Referenced parents cannot be deleted'); END;
CREATE TRIGGER fb_checks_directory_item_insert BEFORE INSERT ON directory_item WHEN EXISTS(SELECT 1 FROM directory_item a WHERE (a.id=NEW.id OR (a.company_id=NEW.company_id AND fb_lower(a.code)=fb_lower(NEW.code))) AND (EXISTS(SELECT 1 FROM checks_checkline WHERE item_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
CREATE TRIGGER fb_checks_directory_item_update BEFORE UPDATE ON directory_item WHEN EXISTS(SELECT 1 FROM directory_item a WHERE (a.id=NEW.id OR (a.company_id=NEW.company_id AND fb_lower(a.code)=fb_lower(NEW.code))) AND a.id<>OLD.id AND (EXISTS(SELECT 1 FROM checks_checkline WHERE item_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
CREATE TRIGGER fb_checks_documents_documentidentity_kept BEFORE DELETE ON documents_documentidentity WHEN EXISTS(SELECT 1 FROM checks_check WHERE identity_id=OLD.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE identity_id=OLD.id) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Referenced parents cannot be deleted'); END;
CREATE TRIGGER fb_checks_documents_documentidentity_insert BEFORE INSERT ON documents_documentidentity WHEN EXISTS(SELECT 1 FROM documents_documentidentity a WHERE (a.id=NEW.id OR (a.company_id=NEW.company_id AND ((a.kind=NEW.kind AND a.number=NEW.number) OR a.request_key=NEW.request_key))) AND (EXISTS(SELECT 1 FROM checks_check WHERE identity_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE identity_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
CREATE TRIGGER fb_checks_documents_documentidentity_update BEFORE UPDATE ON documents_documentidentity WHEN EXISTS(SELECT 1 FROM documents_documentidentity a WHERE (a.id=NEW.id OR (a.company_id=NEW.company_id AND ((a.kind=NEW.kind AND a.number=NEW.number) OR a.request_key=NEW.request_key))) AND a.id<>OLD.id AND (EXISTS(SELECT 1 FROM checks_check WHERE identity_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE identity_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
CREATE TRIGGER fb_checks_ledger_journal_kept BEFORE DELETE ON ledger_journal WHEN EXISTS(SELECT 1 FROM checks_checkrevision WHERE journal_id=OLD.id) OR EXISTS(SELECT 1 FROM checks_checkrevision WHERE reversal_id=OLD.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE journal_id=OLD.id) OR EXISTS(SELECT 1 FROM transfers_transfervoid WHERE journal_id=OLD.id) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Referenced parents cannot be deleted'); END;
CREATE TRIGGER fb_checks_ledger_journal_insert BEFORE INSERT ON ledger_journal WHEN EXISTS(SELECT 1 FROM ledger_journal a WHERE (a.id=NEW.id OR (a.company_id=NEW.company_id AND a.number=NEW.number) OR (NEW.reversal_of_id IS NOT NULL AND a.reversal_of_id=NEW.reversal_of_id) OR (NEW.request_key IS NOT NULL AND a.company_id=NEW.company_id AND a.request_key=NEW.request_key) OR (NEW.source_id IS NOT NULL AND NEW.reversal_of_id IS NULL AND a.source_id=NEW.source_id AND a.reversal_of_id IS NULL)) AND (EXISTS(SELECT 1 FROM checks_checkrevision WHERE journal_id=a.id) OR EXISTS(SELECT 1 FROM checks_checkrevision WHERE reversal_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE journal_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfervoid WHERE journal_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
CREATE TRIGGER fb_checks_ledger_journal_update BEFORE UPDATE ON ledger_journal WHEN EXISTS(SELECT 1 FROM ledger_journal a WHERE (a.id=NEW.id OR (a.company_id=NEW.company_id AND a.number=NEW.number) OR (NEW.reversal_of_id IS NOT NULL AND a.reversal_of_id=NEW.reversal_of_id) OR (NEW.request_key IS NOT NULL AND a.company_id=NEW.company_id AND a.request_key=NEW.request_key) OR (NEW.source_id IS NOT NULL AND NEW.reversal_of_id IS NULL AND a.source_id=NEW.source_id AND a.reversal_of_id IS NULL)) AND a.id<>OLD.id AND (EXISTS(SELECT 1 FROM checks_checkrevision WHERE journal_id=a.id) OR EXISTS(SELECT 1 FROM checks_checkrevision WHERE reversal_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE journal_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfervoid WHERE journal_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
CREATE TRIGGER fb_checks_fb_user_kept BEFORE DELETE ON fb_user WHEN EXISTS(SELECT 1 FROM checks_checkrevision WHERE actor_id=OLD.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE actor_id=OLD.id) OR EXISTS(SELECT 1 FROM transfers_transfervoid WHERE actor_id=OLD.id) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Referenced parents cannot be deleted'); END;
CREATE TRIGGER fb_checks_fb_user_insert BEFORE INSERT ON fb_user WHEN EXISTS(SELECT 1 FROM fb_user a WHERE (a.id=NEW.id OR a.username=NEW.username) AND (EXISTS(SELECT 1 FROM checks_checkrevision WHERE actor_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE actor_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfervoid WHERE actor_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
CREATE TRIGGER fb_checks_fb_user_update BEFORE UPDATE ON fb_user WHEN EXISTS(SELECT 1 FROM fb_user a WHERE (a.id=NEW.id OR a.username=NEW.username) AND a.id<>OLD.id AND (EXISTS(SELECT 1 FROM checks_checkrevision WHERE actor_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfer WHERE actor_id=a.id) OR EXISTS(SELECT 1 FROM transfers_transfervoid WHERE actor_id=a.id))) BEGIN SELECT RAISE(ABORT,'checks_parent_retained: Replacement would discard a referenced parent'); END;
